# orders.py
def checkout(order, user, db, mailer):
    if not user:
        raise ValueError('user')
    total = 0
    for item in order['items']:
        total += item['price'] * item['qty']
    if user.get('vip'):
        total *= 0.9
    db.execute('insert into orders values (?, ?)', user['id'], total)
    mailer.send(user['email'], 'paid', str(total))
    return total

# api.py
def post_checkout(request, db, mailer):
    return {'total': checkout(request['order'], request['user'], db, mailer)}
```

