# config.py
CONFIG = {'timeout': 3, 'retries': 2, 'endpoint': 'https://api.example.test'}

# client.py
from config import CONFIG
def fetch(http, path):
    for attempt in range(CONFIG['retries'] + 1):
        try:
            return http.get(CONFIG['endpoint'] + path, timeout=CONFIG['timeout'])
        except Exception:
            if attempt == CONFIG['retries']:
                raise

# service.py
from client import fetch
def user_name(http, user_id):
    response = fetch(http, '/users/' + str(user_id))
    return response.json()['name']
